/**
 * Array initialization, translated from the original C version.
 *
 * We keep the same numerical initialization as the reference C code,
 * but schedule the initialization Funcs for better throughput
 * (parallel over rows, vectorized over contiguous columns).
 */
static
void init_array(int n, int m,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");
    Func init_A("init_A"), init_C("init_C");

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < m; j++)
    //     A[i][j] = ((i*j+1)%n) / n;
    //
