    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+2)%m) / m;
    //
    // C array C[i][j] is mapped to Buffer C(j, i) with shape (n, n).
    init_C(j, i) = cast<num_t>((i * j + 2) % m) / cast<int>(m);

    // Simple but effective schedule for initialization:
    // - j is the contiguous dimension, so vectorize over j
    // - parallelize over i (rows)
    const int vec = natural_vector_size(type_of<num_t>());

    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    init_C
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Halide Vars and RDom
    //
    // We treat (j, i) as (column, row) indices of C:
    //   logical C[i][j]  <->  C_param(j, i)
    //
    // A is stored with k (the inner-product dimension) as the first
    // (contiguous) dimension:
    //   logical A[i][k]  <->  A_param(k, i)
    //
    // This makes the reduction over k unit-stride in memory.
    Var i("i"), j("j");
    RDom k(0, A.dim(0).extent(), "k"); // k over M (first dimension of A)

    // Build the SYRK kernel in Halide
    // BLAS SYRK (lower triangle):
    //   C := alpha * A * A^T + beta * C
    //
    // Reference C kernel:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express this as:
    //   For all i, j:
    //     if (j <= i):
    //         C_new[i][j] = beta * C[i][j] +
    //                       alpha * sum_k A[i][k] * A[j][k]
    //     else:
    //         C_new[i][j] = C[i][j]        // upper triangle left unchanged
    //
    // In terms of our buffers:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // Note: Halide reductions are defined over rectangular domains.
    // To preserve SYRK semantics while keeping the representation
    // simple, we use a rectangular (i,j) domain and guard the lower
    // triangle with a predicate j <= i. This means we *evaluate* the
    // reduction expression for all (i,j), but we only *use* its
    // result for j <= i, leaving the upper triangle unchanged.

    Func syrk("syrk");

    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper triangle unchanged.
    syrk(j, i) = select(j <= i,
                        beta_expr * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] for lower triangle.
    syrk(j, i) += select(j <= i,
                         alpha_expr * A_param(k, i) * A_param(k, j),
                         Expr((num_t)0));

    // ------------------------------------------------------------------------
    // Schedule
    // ------------------------------------------------------------------------
    //
    // Data layout:
    //   - A_param(k, i): k is contiguous (inner-product dim)
    //   - C_param(j, i): j is contiguous (columns)
    //
    // We tile i and j for cache locality on C, tile k for reuse of A,
    // parallelize across blocks of rows, and vectorize along the
    // contiguous j dimension. This is a blocked SYRK much like a
    // blocked GEMM, but with a triangular guard j <= i.

    // Choose reasonably sized tiles and vector width.
    // We use Halide's natural_vector_size to adapt to the host.
    const int vec = natural_vector_size(type_of<num_t>());

    // Tile sizes; tuned for a general x86-64 CPU, but still reasonable
    // on other CPUs.
    const int tile_i = 32;          // rows of C
    const int tile_j = vec * 4;     // columns of C, multiple of vector width
    const int tile_k = 32;          // reduction dim block

    Var io("io"), jo("jo"), ii("ii"), jj("jj");
    RVar ko("ko"), ki("ki");

    // --------------------
    // Pure step schedule
    // --------------------
    //
    // Layout for pure step (scaling by beta / copying upper triangle):
    //
    //   for io in tiles of i (rows)      [parallel]
    //     for jo in tiles of j (cols)
    //       for ii in rows within tile
    //         for jj in cols within tile [vectorized]
    //
    // i is the "row" index, so we parallelize across blocks of rows
    // (io). j is contiguous, so we vectorize jj.
    syrk
        .compute_root()
        .tile(j, i,  // tile over logical (j, i)
              jo, io,
              jj, ii,
              tile_j, tile_i,
              TailStrategy::GuardWithIf)
        .parallel(io)
        .vectorize(jj, vec);

    // --------------------
    // Update step schedule
    // --------------------
    //
    // For the reduction step, we apply similar tiling in (i,j) and
    // additionally tile the reduction domain k, to improve cache
    // reuse of A and C:
    //
    //   for io in tiles of i (rows)      [parallel]
    //     for jo in tiles of j (cols)
    //       for ko in tiles of k
    //         for ii in rows within tile
    //           for ki in k within tile
    //             for jj in cols within tile [vectorized]
    //
    // Each (io,ii) covers a disjoint band of rows of C, so
    // parallel(io) is race-free. The reduction over k is purely
    // sequential within each (i,j) and not parallelized, which keeps
    // the floating-point reduction order deterministic.
    syrk.update()
        .tile(j, i,
              jo, io,
              jj, ii,
              tile_j, tile_i,
              TailStrategy::GuardWithIf)
        .split(k, ko, ki, tile_k, TailStrategy::GuardWithIf)
        // Reorder so that:
        //   outermost:  io (row tiles)
        //   then:       jo (col tiles)
        //   then:       ko (k tiles)
        //   then:       ii (rows within tile)
        //   then:       ki (k within tile)
        //   innermost:  jj (cols within tile, vectorized)
        .reorder(jj, ki, ii, ko, jo, io)
        .parallel(io)
        .vectorize(jj, vec);

    // Bind ImageParams
    C_param.set(C);
    A_param.set(A);

    // Compile the kernel to machine code
    syrk.compile_jit();

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (in-place semantics w.r.t the original code)
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C array C[ii][jj] -> Buffer C(jj, ii)
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
