    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We'll compute a full N x N Func, with a conditional to restrict
    // updates to the lower triangle.

    Func syrk("syrk");

    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    // Original C value at (i, j)
    Expr orig = C_param(j, i);
    // j <= i indicates we are in the lower triangle (including diagonal)
    Expr in_lower = (j <= i);

    // Pure definition: apply beta scaling to the lower triangle, leave upper
    // triangle unchanged.
    syrk(j, i) = select(in_lower,
                        beta_expr * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] on the lower triangle.
    // For j > i, we add zero so the upper triangle remains as in 'orig'.
    syrk(j, i) += select(in_lower,
                         alpha_expr * A_param(k, i) * A_param(k, j),
                         Expr((num_t)0));

