    // We therefore:
    //   - Tile (i, j) for better cache locality on C.
    //   - Tile and vectorize the reduction dimension k for good SIMD use.
    //   - Parallelize across tiles of i (rows of C), which are independent.

    // Choose tile sizes; these are conservative, portable choices that
    // work well on most modern CPUs. They can be tuned further per-target.
    const int tile_i = 32;  // tile size in i (rows of C)
    const int tile_j = 32;  // tile size in j (cols of C)
    const int tile_k = 32;  // tile size in k (reduction dim)

