    Target target = get_host_target();
    // natural_vector_size gives a hardware-appropriate SIMD width for num_t.
    int vec_k = target.natural_vector_size(type_of<num_t>());
    // Clamp to the tile size to avoid overshooting tile_k.
    vec_k = std::min(vec_k, tile_k);
    if (vec_k < 1) vec_k = 1;

    Var io("io"), jo("jo"), ii("ii"), jj("jj");
    RVar ko("ko"), ki("ki");

    // Compute the entire result at root.
    // Tile over (j, i) to improve locality on C and A.
    // After tiling, the loop nest (for the pure definition) is:
    //   for io (tile of rows i)
    //     for jo (tile of cols j)
    //       for ii (row within tile)
    //         for jj (col within tile)
    //           syrk(jj, ii) = ...
    syrk
        .compute_root()
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i)
        // Make jj (j inner) the innermost loop; ii is next,
        // then jo and io as the outer tile indices.
        .reorder(jj, ii, jo, io)
        // Parallelize over tile rows of C; different io tiles touch
        // disjoint rows of C and are independent.
        .parallel(io);

    // Schedule the update (reduction) similarly, but also tile and
    // vectorize the reduction dimension k.
    syrk.update()
        // Tile the (j, i) loops in the same way as the pure definition.
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i)
        // Split k into ko (outer tile) and ki (inner vectorizable part).
        .split(k, ko, ki, tile_k)
        // Desired loop order inside the reduction:
        //   for io:
        //     for jo:
        //       for ko:
        //         for ii:
        //           for jj:
        //             for ki:   // vectorized
        //               accumulate over A_param(ki, ...) into syrk(jj, ii)
        //
        // We express this with reorder; arguments are specified from
        // innermost to outermost.
        .reorder(ki, jj, ii, ko, jo, io)
        // Vectorize across ki (reduction over k). This gives SIMD
        // dot-products of A[i, *] and A[j, *] with unit-stride loads.
        .vectorize(ki, vec_k)
        // Parallelize the same tile rows as in the pure definition.
        .parallel(io);

    // Bind ImageParams
    C_param.set(C);
    A_param.set(A);

    // Compile the kernel to machine code for the chosen target
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

