    RDom k(0, A.dim(0).extent(), "k"); // k over M

    // Build the SYRK kernel in Halide
    // BLAS SYRK:
    //   C := alpha * A * A^T + beta * C
    //
    // Original C kernel (lower-triangular update):
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
