    //   syrk(j, i) +=
    //       alpha * A[i,k] * A[j,k]   if j <= i
    //       0                         if j > i
    syrk(j, i) += select(j <= i,
                         cast<num_t>(alpha_expr) *
                             A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // ------------------------------------------------------------------------
    // Scheduling: cache-blocking, vectorization, and parallelism
    // ------------------------------------------------------------------------
    //
    // Memory layout recap:
    //   C(j, i): row-major N×N, j (dim 0) is contiguous.
    //   A(k, i): row-major N×M viewed as (k, i); k (dim 0) is contiguous.
    //
    // For each (i, j) in the lower triangle we compute a dot product over k:
    //   sum_k A[i,k] * A[j,k]  ->  A_param(k, i), A_param(k, j)
    // which walks A contiguously along k for both rows i and j. This is
    // a good target for SIMD vectorization along k.
    //
    // We block i, j, and k to improve cache locality and parallelize over
    // tiles of rows (i) of C. We also vectorize the reduction over k.

    // Tunable tile sizes. These are conservative defaults chosen to work
    // well on modern CPUs; they can be adapted if needed.
    const int tile_i = 32;   // tile size for i (rows of C)
    const int tile_j = 32;   // tile size for j (cols of C)
    const int tile_k = 32;   // tile size for k (reduction dim)

