    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Vars/RVars introduced by tiling and splitting.
    Var io("io"), jo("jo"), ii("ii"), jj("jj");
    RVar ko("ko"), ki("ki");

    // Pure stage schedule:
    //
    // - Tile (j, i) into (jo, io) outer tiles and (jj, ii) intra-tile coords.
    //   tile(j, i, jo, io, jj, ii, tile_j, tile_i) produces loops:
    //     for io:
    //       for jo:
    //         for ii:
    //           for jj:
    // - Reorder so that within each tile we iterate ii (rows) outer, jj (cols) inner
    //   and keep io as the outermost tile dimension.
    // - Parallelize across io (blocks of rows of C).
    // - Vectorize across jj to do contiguous SIMD loads/stores on C.
    syrk
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i)
        .reorder(jj, ii, jo, io)
        .parallel(io)
        .vectorize(jj, vec_width);

    // Update (reduction) stage schedule:
    //
    // We use the same tiling for (j, i), then additionally split the
    // reduction variable k into outer ko and inner ki:
    //   k = ko * tile_k + ki, ki in [0, tile_k)
    //
    // We then reorder loops to:
    //   for io (parallel over row-tiles of C)
    //     for jo
    //       for ko  (tiles of k)
    //         for ii
    //           for jj
    //             for ki (vectorized)
    //
    // This gives:
    //   - good reuse of A and C tiles inside cache
    //   - contiguous SIMD operations over ki (k) using A_param(k, i/j)
    //   - parallelism across independent row tiles of C (io)
    syrk.update()
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i)
        .split(k, ko, ki, tile_k)
        // Reorder arguments from innermost to outermost:
        //   innermost: ki, then jj, then ii, then ko, then jo, then io (outermost)
        .reorder(ki, jj, ii, ko, jo, io)
        .parallel(io)
        .vectorize(ki, vec_width);

    // Bind ImageParams
    C_param.set(C);
    A_param.set(A);

    // Compile the kernel to machine code for the chosen target
    syrk.compile_jit(target);

