    // Simple, cache-friendly schedule for initialization:
    // - parallelize across rows (i)
    // - vectorize across columns (j), taking advantage of j being stride-1.
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, 8);

    init_C
        .compute_root()
        .parallel(i)
        .vectorize(j, 8);

    init_A.realize(A);
    init_C.realize(C);
