    syrk
        .tile(j, i,    // original Vars
              jo, io,  // outer tile indices: jo -> j tiles, io -> i tiles
              jj, ii,  // inner indices inside a tile
              tile_j, tile_i,
              TailStrategy::GuardWithIf)
        // Loop order (outermost to innermost): io, jo, ii, jj.
